  }

  List<int> dpKey = List<int>.filled(word.length + 1, 0);
  for (int i = 0; i <= word.length; i++) {
    dp[word[i]] = [];
  }

  List<List<int>> segmentations = [];
  for (int i = 0; i <= word.length; i++) {
    if (isPrefix(word.substring(0, i + 1), i + 1)) {

      for (int j = 0; j < i; j++) {
        if (isPrefix(word.substring(j + 1, i + 1), i - j)) {
          String prefix = word.substring(j + 1, i + 1);
          dp[prefix]!.add(j);
          segmentations.add([prefix, j + 1, i + 1]);
        }
      }
    }
  }

