  Set<String> wordSet = wordDict.toSet();
  int n = s.length;
  List<List<String>> result = [];

  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (!dp[n]) {
    result.add([]);
