  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != 999999999 && wordSet.contains(s.substring(j, i))) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }

  return dp[n] == 999999999 ? 0 : dp[n];
}

