List<List<String>> generateCombinations(List<String> items, int k) {
  if (k == 0) return [[]]; 
  if (k > items.length) {
    print('First argument must be an integer k (size of combinations). Got: $k');
    return <List<String>>[];
  }

  final List<List<String>> prev = generateCombinations(items, k - 1);
  final List<List<String>> result = <List<String>>[];

  for (int i = 0; i < prev.length; i++) {
    for (int j = 0; j < items.length; j++) {
      final List<String> copy = <String>[];
      for (String s in prev[i]) copy.add(s);
      copy.add(items[j]);
      if (copy.length == k) {
        result.add(copy);
      }
    }
  }
  return result;
}

