  Map<String, int> counts = {'Clubs': 0, 'Diamonds': 0, 'Hearts': 0, 'Spades': 0};
  const suitMasks = {'Clubs': 1, 'Diamonds': 2, 'Hearts': 4, 'Spades': 8};
  int handMask = 0;
  int i = 0;
  while (i < hand.length) {
    String suit = hand[i];
    int mask = suitMasks[suit]!;
    int start = i;
    while (i < hand.length && (handMask & mask) != 0) {
      handMask |= mask;
      i++;
    }
    int runLen = i - start;
    if (runLen > 1) {
      int rank = hand.codeUnitAt(start) - 48;
      counts[suit] = (counts[suit]! + rank) % 10;
    }
    i++;
  }
  return counts;
}

