  for (int i = 0; i < row; i++) {
    if (board[i][col] == 1) return false;
  }

  int i = row - 1;
  int j = col - 1;
  while (i >= 0 && j >= 0) {
    if (board[i][j] == 1) return false;
    i--;
    j--;
  }

  i = row - 1;
  j = col + 1;
  while (i >= 0 && j < n) {
    if (board[i][j] == 1) return false;
    i--;
    j++;
  }

  return true;
}

