void solveNQueens(int n) {

  const int cols = n;
  final int totalSolutions = 1 << cols;

  bool isSafe(int row, int col) {

    for (int r = 0; r < row; r++) {
      if (board[r][col] == 1) return false;
    }

    int r = row - 1;
    int c = col - 1;
    while (r >= 0 && c >= 0) {
      if (board[r][c] == 1) return false;
      r--;
      c--;
    }

    r = row - 1;
    c = col + 1;
    while (r >= 0 && c < cols) {
      if (board[r][c] == 1) return false;
      r--;
      c++;
    }

    return true;
  }

  void placeQueen(int row) {
    if (row == cols) {
      print('Solution ${solutionIndex} confirmed!');
      solutionIndex++;
      return;
    }

    for (int col = 0; col < cols; col++) {
      if (isSafe(row, col)) {

        board[row][col] = 1;

        placeQueen(row + 1);

        board[row][col] = 0;
      }
    }
  }

  int solutionIndex = 0;

  final int size = 1 << 20;
  final int capacity = size + totalSolutions;
  final int threshold = capacity ~/ 2;

  final List<int> heap = List<int>.filled(capacity, 0);
  final int heapIndex = 0;

  heap[heapIndex] = solutionIndex;
  solutionIndex++;

  while (heapIndex < capacity) {
    final int index = heap[heapIndex];
    heapIndex++;

    if (index >= threshold) break;

    final int row = index ~/ cols;
    final int col = index % cols;

    for (int r = row + 1; r < cols; r++) {
      if (isSafe(r, col)) {

        board[r][col] = 1;

        final int newIndex = solutionIndex;
        solutionIndex++;

        heap[heapIndex] = newIndex;
        heapIndex++;

        board[r][col] = 0;
      }
    }
  }

  print('Total solutions: ${solutionIndex - 1}');
}

