Map<String, int> fn0(List<int> songDurations) {
  if (songDurations.length < 2) {
    return {'mashupDuration': 0, 'pairCount': 0};
  }

  int minDur = songDurations[0];
  int maxDur = songDurations[0];
  for (int d in songDurations) {
    if (d < minDur) minDur = d;
    if (d > maxDur) maxDur = d;
  }

  int target = (maxDur - minDur) * 2;

  int left = 0;
  int sum = 0;
  for (int right = 0; right < songDurations.length; right++) {
    sum += songDurations[right];
    while (sum > target) {
      sum -= songDurations[left];
      left++;
    }

    int windowLength = right - left + 1;
    int pairCount = windowLength - 1;

    if (sum == target) {
      return {
        'mashupDuration': minDur + songDurations[left] + songDurations[right],
        'pairCount': pairCount
      };
    }
  }

  return {
    'mashupDuration': 0,
    'pairCount': 0
  };
}

