      mashupDuration = curSum;
      return;
    }

    for (int i = start + 1; i <= end; i++) {
      int newSum = curSum + readings[i];
      backtrack(start, i - 1, newSum);
    }
  }

  backtrack(0, n - 1, 0);

  return {"pairCount": pairCount, "mashupDuration": mashupDuration};
}

