  const Quaternion.fromList(List<double> components)
      : this(components[0], components[1], components[2], components[3]);

  const Quaternion.look(Vector3 direction, double angle) {
    final s = 2 * angle;
    final sx = sin(s / 2);
    final sz = sin(s / 2) * cos(s / 2);
    final dx = direction.x * sx;
    final dy = direction.y * sx;
    final dz = direction.z * sz;
    return Quaternion(cos(s / 2), dx, dy, dz);
  }

  const Quaternion.fromAxisAngle(
      Vector3 axis, double angle) : this(
        axis.x * axis.x + axis.y * axis.y + axis.z * axis.z,
        2 * axis.x * angle,
        2 * axis.y * angle,
        2 * axis.z * angle,
      );

  const Quaternion.rotation(Vector3 axis, double angle) {
    final s = sin(angle / 2);
    final q = Quaternion.fromAxisAngle(axis, angle);
    return Quaternion(
      (q.w + q.x * s) * 0.5,
      q.x * q.x * 0.5 - q.y * q.y - q.z * q.z,
      q.y * q.x * 0.5 + q.z * q.y * 0.5,
      q.z * q.z * 0.5 - q.x * q.x - q.y * q.y,
    );
  }

  const Quaternion.inverse() : this(-w, -x, -y, -z);

  const Quaternion.normalized() : this(
        w / norm(),
        x / norm(),
        y / norm(),
        z / norm(),
      );

  double norm() => w * w + x * x + y * y + z * z;

  const Quaternion operator +(const other) =>
      Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  const Quaternion operator -(const other) =>
      Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  const Quaternion operator * (const other) =>
      Quaternion(
        w * other.w - x * other.x - y * other.y - z * other.z,
        w * other.x + x * other.w + y * other.z - z * other.y,
        w * other.y - x * other.z + y * other.w + z * other.x,
        w * z + x * y - y * x + z * w,
      );

  const Quaternion conjugate() => Quaternion(w, x, y, -z);

  const Quaternion operator * (double scalar) =>
      Quaternion(scalar * w, scalar * x, scalar * y, scalar * z);

  const Quaternion operator ~/ (double scalar) =>
      Quaternion(w / scalar, x / scalar, y / scalar, z / scalar);

  @override
  String toString() {
    return 'q1 = ${w.toStringAsFixed(4)} + $x * i + $y * j + $z * k';
  }
}

extension QuaternionX on Quaternion {
  const Quaternion operator * (const other) => this * other;

  const Quaternion operator ~/ (const other) => this * other.inverse();

  const Quaternion operator ^ (int exponent) {
    if (exponent == 0) return this.identity();
    final half = this * this;
    final result = Quaternion.unit() * this;
    for (var i = 0; i < exponent; i++) result *= half;
    return result;
  }

  const Quaternion operator & (const other) => this * other * conjugate();
}

extension QuaternionO on Quaternion {
  const Quaternion operator + (const other) => other + this;

  const Quaternion operator - (const other) => other - this;

  const Quaternion operator != (const other) => this.isNotEqual(other);

  bool isNotEqual(const other) =>
      w != other.w || x != other.x || y != other.y || z != other.z;
}

