class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  const Quaternion.fromAxisAngle(
    List<double> axis,
    double angle,
  ) : x = axis[0] * cos(angle / 2),
        y = axis[1] * sin(angle / 2),
        z = axis[2] * sin(angle / 2),
        w = cos(angle / 2);

  const Quaternion.fromBasis(List<double> basis)
      : x = basis[0],
        y = basis[1],
        z = basis[2],
        w = basis[3];

  Quaternion operator +(const Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(const Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(const Quaternion other) =>
      Quaternion(
        x * other.w - z * other.y,
        y * other.w + x * other.z,
        z * other.w + y * other.x,
        w * other.w,
      );

  Quaternion operator ^(const Quaternion other) =>
      Quaternion(
        w * other.x + z * other.y,
        y * other.x - w * x,
        x * other.z - y * other.w,
        z * other.w - w * x,
      );

  Quaternion get conjugate => Quaternion(x, y, z, -w);

  Quaternion get normalized => this / norm();

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  void rotateVector(List<double> v) {
    List<double> result = List<double>.filled(4, 0.0);
    for (int i = 0; i < v.length; i++) {
      result[i] = v[i] *
          (2 * x * v[i] + 2 * y * v[i] * z - 2 * z * v[i] * y + 2 * w * v[i] * x);
    }
    for (int i = 3; i > 0; i--) {
      double temp = result[i - 1];
      result[i - 1] = result[i];
      result[i] = temp;
    }
  }

  void rotate90(List<double> v) {
    for (int i = 0; i < v.length; i++) {
      result[i] = v[i] *
          (2 * x * v[i] + 2 * y * v[i] * z - 2 * z * v[i] * y + 2 * w * v[i] * x);
    }
  }
}

