class Quaternion {
  double x, y, z, w;
  const Quaternion(this.x, this.y, this.z, this.w);

  static const Quaternion zero = Quaternion(0.0, 0.0, 0.0, 0.0);
  static const Quaternion unit = Quaternion(1.0, 0.0, 0.0, 0.0);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

