    double sin = angle * 0.5;
    double cos = angle * 0.5;

    double x = axis.x, y = axis.y, z = axis.z;
    return Quaternion(
      cos * x * x + sin * z * y,
      cos * y * y + sin * x * z,
      cos * z * z + sin * y * x,
