  const Quaternion.unit() : this(0, 0, 0, 1);

  const Quaternion.fromList(List<double> parts)
      : this(parts[0], parts[1], parts[2], parts[3]);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ,
                                  double angle) {
    double c = cos(angle / 2);
    double s = sin(angle / 2);
    return Quaternion(axisX * c - axisY * s,
                    axisY * c + axisX * s,
                    axisZ * c - axisW * s,
                    axisW * c + axisZ * s);
  }

  const Quaternion.fromBasis(List<double> axes) {
    return Quaternion(axes[0], axes[1], axes[2], axes[3]);
  }

  const Quaternion.random() {
    List<double> parts = List.generate(4, (_) => randomDouble() * 2 - 1);
    return Quaternion.fromList(parts);
  }

  Quaternion operator +(const Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(const Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(const Quaternion other) {
    double q14 = x * other.w - y * other.z - z * other.y + w * other.x;
    double q24 = x * other.z + y * other.w + z * other.y - w * other.x;
    return Quaternion(q14, q24, z * other.x - w * other.y, x * other.w + y * other.z);
  }

