    x = x * other.w - y * other.z - z * other.y + w * other.x;
    y = x * other.z + y * other.w + z * other.y - w * other.x;
    z = z * other.x - w * other.y;
    w = w * other.w + x * other.z;
    return this;
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  Quaternion normalized() {
    double norm = norm();
    if (norm == 0) {
      return Quaternion.zero();
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion inverse() {
    double norm = norm();
    if (norm == 0) {
      return Quaternion.zero();
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm) * conjugate();
  }

  @override
  String toString() {
    double r = sqrt(x * x + y * y + z * z + w * w);
    double a = 2 * atan2(r, w);
    String sign = r >= 0 ? '+' : '-';
    return 'Quaternion(${x.toStringAsFixed(2)}, ${y.toStringAsFixed(2)}, ${z.toStringAsFixed(2)}, $sign${a.toStringAsFixed(2)} rad)';
  }

  static Quaternion rotate(Quaternion q1, double angle) {
    double c = cos(angle / 2);
    double s = sin(angle / 2);
    return Quaternion(
        q1.x * c - q1.z * s,
        q1.y * c + q1.z * s,
        q1.z * c - q1.x * s,
        q1.w * c + q1.x * s);
  }
}

