      if (norm() == 0) Quaternion.zero() else this * conjugate();

  Quaternion rotateZ(double angle) =>
      Quaternion.fromAxisAngle(0, 0, 1, angle) * this;

  Quaternion rotateY(double angle) =>
      Quaternion.fromAxisAngle(0, 1, 0, angle) * this;

  Quaternion rotateX(double angle) =>
      Quaternion.fromAxisAngle(1, 0, 0, angle) * this;

  @override
  String toString() =>
      'q1 = ${toString(w)} + ${toString(x)}i + ${toString(y)}j + ${toString(z)}k';
}

