    final double cos = s > 1.0 ? 1.0 / s : 1.0 - s;
    final double sin = s > 1.0 ? sqrt(s - 1.0) : sqrt(s);
    return Quaternion._internal(cos * ax, cos * ay, cos * az, sin * ax * ay + az * az);
  }

  const Quaternion.fromAxisAngleComplex(List<double> axis, List<double> phase) {
    final double ax = axis[0], ay = axis[1], az = axis[2];
    final double s = 2 * phase[2];
    final double cos = s > 1.0 ? 1.0 / s : 1.0 - s;
    final double sin = s > 1.0 ? sqrt(s - 1.0) : sqrt(s);
    return Quaternion._internal(cos * ax, cos * ay, cos * az, sin * ax * ay + az * az);
  }

