    return Quaternion._internal(x, y, z, w);
  }

  const Quaternion.fromPolar(double r, double theta) {
    final double cos = cos(theta);
    return Quaternion._internal(r * cos, r * sin(theta) * x, r * sin(theta) * y, r * sin(theta) * z);
  }

  const Quaternion.fromCartesian(List<double> cart) {
    final double x = cart[0], y = cart[1], z = cart[2];
    final double w = sqrt(x * x + y * y + z * z);
    return Quaternion._internal(x / w, y / w, z / w, w / w);
  }

  const Quaternion.fromQuaternion(List<double> q) {
    final double x = q[0], y = q[1], z = q[2], w = q[3];
    return Quaternion._internal(x, y, z, w);
  }

  const Quaternion.fromList(List<double> data) {
    if (data.length != 4) {
      throw ArgumentError('Invalid quaternion data');
    }
    return Quaternion._internal(data[0], data[1], data[2], data[3]);
  }

  const Quaternion.fromListComplex(List<double> data) {
    final double x = data[0], y = data[1], z = data[2], w = data[3];
    final double t = sqrt(x * x + y * y + z * z);
    return Quaternion._internal(x / t, y / t, z / t, w / t);
  }

  double get real => x;
  double get imag => y;
  double get imp => z;
  double get norm => x * x + y * y + z * z + w * w;

  const Quaternion operator +(List<double> other) {
    final double rx = x + other[0], ry = y + other[1], rz = z + other[2], rw = w + other[3];
    return Quaternion._internal(rx, ry, rz, rw);
  }

  const Quaternion operator -(List<double> other) {
    final double rx = x - other[0], ry = y - other[1], rz = z - other[2], rw = w - other[3];
    return Quaternion._internal(rx, ry, rz, rw);
  }

  const Quaternion operator -() {
    return Quaternion._internal(-x, -y, -z, w);
  }

  const Quaternion operator *(List<double> other) {
    final double ax = x, ay = y, az = z, aw = w;
    final double bx = other[0], by = other[1], bz = other[2], bw = other[3];
    double rx = x * bx - y * bz - z * by + aw * bw;
    double ry = x * bz + y * bx - z * ax + aw * bw;
    double rz = x * by + y * az - z * ax + aw * bw;
    double rw = x * bw + y * bw - z * bx - aw * ax;
    return Quaternion._internal(rx, ry, rz, rw);
  }

  const Quaternion operator *=(List<double> other) {
    final double ax = x, ay = y, az = z, aw = w;
    final double bx = other[0], by = other[1], bz = other[2], bw = other[3];
    x = x * bx - y * bz - z * by + aw * bw;
    y = x * bz + y * bx - z * ax + aw * bw;
    z = x * by + y * az - z * ax + aw * bw;
    w = x * bw + y * bw - z * bx - aw * ax;
    return this;
  }

  const Quaternion operator /(List<double> other) {
    final double a0 = x, a1 = y, a2 = z, a3 = w;
    final double b0 = other[0], b1 = other[1], b2 = other[2], b3 = other[3];
    final double denom = b0 * b0 + b1 * b1 + b2 * b2 + b3 * b3;
