        (a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3) / denom,
        (a1 * b0 - a0 * b1) / denom,
        (a2 * b0 - a0 * b2) / denom,
        (a3 * b0 - a0 * b3) / denom);
  }

  const Quaternion conjugate() {
    return Quaternion._internal(x, y, z, -w);
  }

  const Quaternion inverse() {
    final double n = norm;
    return Quaternion._internal(x / n, y / n, z / n, w / n);
  }

  const Quaternion normalized() {
    final double n = norm;
    return Quaternion._internal(x / n, y / n, z / n, w / n);
  }

  @override
  String toString() {
    return 'q1 = $x + $y*i + $z*j + $w*k';
  }
