  final int minY = target[1] - maxDiff, maxY = target[1] + maxDiff;
  if (maxX <= minX || maxY <= minY) return [-1, -1];

  final List<List<int>> zones = <List<int>>[];
  for (int i = 0; i < n; i++) {
    final int x1 = shelves[i][0] - maxDiff, x2 = shelves[i][0] + maxDiff;
    final int y1 = shelves[i][1] - maxDiff, y2 = shelves[i][1] + maxDiff;
    if (x1 <= minX && x2 >= maxX && y1 <= minY && y2 >= maxY) {
      zones.add([i, shelves[i]]);
    }
  }

  if (zones.isEmpty) return [-1, -1];

  final List<int> minDistances = <int>[];
  for (final List<int> zone in zones) {
    int minX = zone[0], maxX = zone[0], minY = zone[1], maxY = zone[1];
    for (final List<int> p in zone) {
      if (p[0] < minX) minX = p[0];
      if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1];
      if (p[1] > maxY) maxY = p[1];
