class Rectangle {
  final double width;
  final double height;
  final double minX;
  final double maxX;
  final double minY;
  final double maxY;
  const Rectangle(this.width, this.height, [this.minX = 0, this.maxX = 0, this.minY = 0, this.maxY = 0]);

  Rectangle.origin() : this(1, 1);
  Rectangle.unit() : this(2, 2);
  Rectangle.unitY() : this(2, 1);
  Rectangle.unitX() : this(1, 2);

  Rectangle.point(Point p1, Point p2)
      : this(p1.x - p2.x, p1.y - p2.y, p1.x, p2.x, p1.y, p2.y);

  Rectangle.originUnitY() : this(1, 2);
  Rectangle.originUnitX() : this(2, 1);
  Rectangle.unitYUnitX() : this(2, 2);

  Rectangle.zero() : this(0, 0, 0, 0, 0, 0);

  Rectangle.square(double side) : this(side, side);

  Rectangle.expand(double delta) : this(width + delta, height + delta, minX - delta, maxX + delta, minY - delta, maxY + delta);

  bool contains(Point p) {
    return p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY;
  }

  bool contains(Rectangle r) {
    return r.contains(Point(minX, minY)) && contains(Point(maxX, maxY));
  }

  bool overlaps(Rectangle r) {
    return !(!contains(r) && !r.contains(this));
  }

  bool touches(Rectangle r) {
    return overlaps(r) && (minX == r.maxX || maxX == r.minX) && (minY == r.maxY || maxY == r.minY);
  }

  bool hasSameCenter(Rectangle r) {
    return (minX + maxX) / 2 == (r.minX + r.maxX) / 2 && (minY + maxY) / 2 == (r.minY + r.maxY) / 2;
  }

  Rectangle union(Rectangle r) {
    return Rectangle(
      width * 2,
      height * 2,
      minX < r.minX ? minX : r.minX,
      maxX > r.maxX ? maxX : r.maxX,
      minY < r.minY ? minY : r.minY,
      maxY > r.maxY ? maxY : r.maxY,
    );
  }

  Rectangle intersection(Rectangle r) {
    if (!overlaps(r)) return Rectangle.zero();
    return Rectangle(
      width * (maxX < r.minX ? r.minX : maxX),
      height * (maxY < r.minY ? r.minY : maxY),
      minX < r.minX ? r.minX : maxX,
      minX > r.maxX ? r.maxX : maxX,
      minY < r.minY ? r.minY : maxY,
      minY > r.maxY ? r.maxY : maxY,
    );
  }

  Rectangle translate(Point p) {
    return Rectangle(
      width,
      height,
      p.x + minX,
      p.x + maxX,
      p.y + minY,
      p.y + maxY,
    );
  }

  @override
  String toString() {
    return 'Rectangle(center: (${centerX}, ${centerY}), width: $width, height: $height)';
  }

  final double centerX = (minX + maxX) / 2;
  final double centerY = (minY + maxY) / 2;
}

