    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 4.0],
    [4.0, 4.5],
    [2.0, 2.0],
    [3.5, 5.0],
    [1.0, 1.5],
    [7.0, 0.0],
    [5.0, 1.5],
  ];

  int k = 3;
  double eps = 0.5;
  int maxIterations = 50;

  final int n = points.length;

  List<int> labels = List.filled(n, -1);

  int find(int i) {
    if (labels[i] < 0) {
      labels[i] = i;
    }
    return labels[i];
  }

  void union(int a, int b) {
    if (find(a) != find(b)) {
      labels[find(a)] = find(b);
    }
  }

  List<List<int>> centroids = List.generate(k, (_) => List.filled(2, 0));

  for (int i = 0; i < k; i++) {
    int idx = rand.nextInt(n);
    centroids[i] = points[idx].toList();
  }

  int clusterId = 0;
  bool converged = false;

  for (int iter = 0; iter < maxIterations && !converged; iter++) {
    List<List<int>> pointsPerCluster = List.generate(k, (_) => []);

    for (int i = 0; i < n; i++) {
      double minDist = double.infinity;
      int bestIdx = -1;

      for (int j = 0; j < k; j++) {
        double dist = (points[i][0] - centroids[j][0]).abs() + (points[i][1] - centroids[j][1]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestIdx = j;
        }
      }

      union(clusterId, bestIdx);
      pointsPerCluster[bestIdx].add(i);
    }

    List<List<int>> newCentroids = List.generate(k, (_) => List.filled(2, 0));

    for (int c = 0; c < k; c++) {
      List<int> pointsOfCluster = pointsPerCluster[c];
      if (pointsOfCluster.isEmpty) {
        newCentroids[c] = centroids[c];
        continue;
      }

      int totalX = 0;
      int totalY = 0;
      int cnt = 0;

      for (int p in pointsOfCluster) {
        totalX += points[p][0];
        totalY += points[p][1];
        cnt++;
      }

      newCentroids[c][0] = totalX / cnt;
      newCentroids[c][1] = totalY / cnt;
    }

    for (int i = 0; i < k; i++) {
      centroids[i] = newCentroids[i];
    }

    int uniqueClusters = 0;
    Set<int> usedClusters = {};

    for (int i = 0; i < n; i++) {
      if (find(i) == i) {
        uniqueClusters++;
        usedClusters.add(i);
      }
    }

    if (uniqueClusters == k) {
      converged = true;
    }
  }

  print('Converged in $iter iteration(s).');

  List<List<int>> pointsPerCluster = List.generate(k, (_) => []);

  for (int i = 0; i < n; i++) {
    if (find(i) != i) {
      continue;
    }
    pointsPerCluster[find(i)].add(i);
