    double minDist = double.infinity;
    var nearest = 0;
    for (var j = 0; j < n; j++) {
      var d = (i - data[j][0]).abs() + (data[j][1] - i).abs();
      if (d < minDist) { minDist = d; nearest = j; }
    }
    return <int>[nearest];
  }

  List<int> emptyClusters() {
    final List<int> empty = <int>[];
    for (var c in clusters) {
      if (c.isEmpty) empty.add(c.length);
    }
    return empty;
  }

  var converged = false;
