  List<double> centroids = List.generate(k, (i) => double.infinity);

  int findClosestCluster(int pointIdx) {
    double minDistance = double.infinity;
    int closestCluster = 0;
    for (int i = 0; i < k; i++) {
      double dist = (data[pointIdx][0] - centroids[i]).abs() + (data[pointIdx][1] - centroids[i]).abs();
      if (dist < minDistance) {
        minDistance = dist;
        closestCluster = i;
      }
    }
    return closestCluster;
  }

  double distance(int i, int j) {
    double x1 = data[i][0], y1 = data[i][1];
    double x2 = data[j][0], y2 = data[j][1];
    return (x1 - x2).abs() + (y1 - y2).abs();
  }

  for (int iter = 0; iter < maxIterations; iter++) {

    for (int i = 0; i < data.length; i++) {
      if (clusterAssignments[i] == -1) {
        clusterAssignments[i] = findClosestCluster(i);
      }
    }

    List<List<double>> clusterData = List.generate(k, (i) => List<double>.from(data.sublist(clusterAssignments[i] * 2, (clusterAssignments[i] * 2) + 2)));

    centroids = List.generate(k, (i) => {
      double sumX = 0, sumY = 0, count = 0;
      for (var point in clusterData[i]) {
        sumX += point[0];
        sumY += point[1];
        count++;
      }
      return [sumX / count, sumY / count];
    });

    List<int> newClusterAssignments = List.filled(data.length, -1);
    for (int i = 0; i < data.length; i++) {
      for (int j = 0; j < k; j++) {
        if (distance(i, j) < distance(i, clusterAssignments[i])) {
          newClusterAssignments[i] = j;
          break;
        }
      }
    }

    bool changed = false;
    for (int i = 0; i < data.length; i++) {
      if (newClusterAssignments[i] != clusterAssignments[i]) {
        changed = true;
        clusterAssignments[i] = newClusterAssignments[i];
      }
    }

    if (!changed) break;

    if (iter % 10 == 0) {
      print('Converged in $iter iteration(s).');
    }
  }

  for (int i = 0; i < k; i++) {
    print('Cluster $i:');
    print('  Points: ${clusterAssignments.sublist(i * 2, (i * 2) + 2)}');
    print('  centroid: ${centroids[i]}');
  }
}

