Map<String, int> fn0(List<List<int>> board) {
  if (board.isEmpty) return {'segmentCount': 0, 'totalPassableCells': 0, 'minSegmentLength': 0, 'maxSegmentLength': 0, 'maxSegmentScore': 0};
  int rows = board.length;
  int cols = board[0].length;
  List<List<bool>> valid = List.generate(rows, (_) => List<bool>.filled(cols, false));

  int dfs(int r, int c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return 0;
    if (board[r][c] == 0) return 0;
    if (valid[r][c]) return 1;
    valid[r][c] = true;

    int count = 0;
    int up = dfs(r + 1, c);
    if (up > 0) count++;
    int down = dfs(r - 1, c);
    if (down > 0) count++;
    int left = dfs(r, c - 1);
    if (left > 0) count++;
    int right = dfs(r, c + 1);
    if (right > 0) count++;
    return count;
  }

  int maxScore = 0;
  int bestLength = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (board[r][c] == 1 && valid[r][c]) {
        int len = dfs(r, c);
        if (len > bestLength) {
          bestLength = len;
          maxScore = len * board[r][c];
        }
      }
    }
  }

  return {'segmentCount': rows * cols - (rows + cols), 'totalPassableCells': rows * cols - (rows + cols + 1), 'minSegmentLength': bestLength, 'maxSegmentLength': bestLength, 'maxSegmentScore': maxScore};
}

