Set<int> fn0(List<String> maze) {
  if (maze.isEmpty) return {};
  final int rows = maze.length;
  final int cols = maze[0].length;
  final List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  final Set<int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      final String cell = maze[i][j];
      if (cell == '#' || cell == '.') continue;
      dp[i][j] = 0;
      if (i > 0) {
        final int up = maze[i-1][j];
        if (up == '#') continue;
        if (up == '.') {
          if (dp[i-1][j] == 0) dp[i][j] = 1;
        } else if (up == 'N' || up == 'S') {
          if (dp[i-1][j] == 1) dp[i][j] = 2;
        }
      }
      if (j > 0) {
        final int left = maze[i][j-1];
        if (left == '#') continue;
        if (left == '.') {
          if (dp[i][j-1] == 0) dp[i][j] = 3;
        } else if (left == 'E' || left == 'W') {
          if (dp[i][j-1] == 1) dp[i][j] = 4;
        }
      }
      if (dp[i][j] == 4) {
        result.add(i * cols + j);
      }
    }
  }
  return result;
}

