  int n = items.length;
  if (n == 0) return result;

  int minCapacity = items[0] * n;
  int maxCapacity = (items[0] + 1) * n;

  while (minCapacity < maxCapacity) {
    int mid = (minCapacity + maxCapacity) ~/ 2;
    int totalWeight = 0;

    for (int i = 0; i < n; i++) {
      int count = mid ~/ (items[i] * n);
      totalWeight += count * items[i] * n;
    }

