bool fn0(List<int> modulePositions, int sensitivity) {
  if (modulePositions.isEmpty) return sensitivity == 0;
  int left = 0;
  int right = modulePositions.length - 1;
  int minLen = modulePositions.length;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    if (modulePositions[mid] - modulePositions[0] <= sensitivity) {
      minLen = mid + 1;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return minLen == sensitivity + 1;
}

